    title:data.title,category:"Cities",eyebrow:data.eyebrow,infoboxKicker:data.infoboxKicker,
    infoboxTitle:data.infoboxTitle||data.title,lead:data.lead,canon:data.canon,sections:data.sections,
    related:data.related||geacpsCapitalRelated,sources:[...geacpsCapitalSources,...(data.additionalSources||[])],
